export const sceneDefaults={"0": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "#8aa4a8", "hidden": false}, "1": {"x": -1.4, "y": -1, "z": -2.6, "size": 1, "rx": 0, "ry": 5, "rz": 0, "color": "#98b3b3", "hidden": false}, "8": {"x": 0, "y": -1.2, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}, "9": {"x": -0.6, "y": -0.4, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "#69917f", "hidden": false}, "10": {"x": 1.2, "y": -1.6, "z": -0.1, "size": 1.4, "rx": 0, "ry": 0, "rz": 0, "color": "#6a9571", "hidden": false}, "11": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}, "12": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": true}, "13": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}, "14": {"x": 0, "y": 0, "z": 4.1, "size": 1.7, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": true}, "15": {"x": 1.2, "y": 1.2, "z": 0, "size": 1.2, "rx": 0, "ry": 180, "rz": 0, "color": "#7eb485", "hidden": false}, "16": {"x": 0, "y": -3.4, "z": -0.9, "size": 1.6, "rx": 0, "ry": 0, "rz": 0, "color": "#6a906b", "hidden": false}, "17": {"x": -0.9, "y": -0.2, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}, "18": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}, "19": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}, "20": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}, "21": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}, "22": {"x": 0, "y": 0, "z": 0, "size": 1, "rx": 0, "ry": 0, "rz": 0, "color": "", "hidden": false}};
export function prepareLayout(THREE,entries){
 entries.forEach((e,i)=>{e.id=String(i<2?i:i+6);e.node=new THREE.Group();e.object.parent.add(e.node);if(e.plant){e.node.position.copy(e.object.position);e.object.position.set(0,0,0);}e.node.add(e.object);e.origin=e.node.position.clone();e.materials=[];if(e.plant)e.object.traverse(o=>{if(o.isMesh&&o.material?.color){o.material=o.material.clone();e.materials.push({mat:o.material,color:o.material.color.clone(),emissive:o.material.emissive?.clone()});}});});
}
export function applyLayout(entries,state,i){const e=entries[i],s=state[i];e.node.visible=!(e.plant&&s.hidden===true);for(const axis of ['x','y','z']){s[axis]=Math.max(-12,Math.min(12,Number(s[axis])||0));e.node.position[axis]=e.origin[axis]+s[axis];}s.size=Math.max(.2,Math.min(3,Number(s.size)||1));e.node.scale.setScalar(e.plant?s.size:1);e.node.rotation.set(...['rx','ry','rz'].map(k=>e.plant?(Number(s[k])||0)*Math.PI/180:0));for(const m of e.materials){m.mat.color.copy(m.color);if(/^#[0-9a-f]{6}$/i.test(s.color))m.mat.color.set(s.color);if(m.emissive)m.mat.emissive.copy(m.mat.color);}}
